def dual_case_manifest_b64() -> str:
    """Manifest with both ``Users`` and ``users`` as separate models."""
    manifest = {
        "catalog": "my_catalog",
        "schema": "my_schema",
        "models": [_model("Users"), _model("users"), _model("Orders")],
    }
    return base64.b64encode(orjson.dumps(manifest)).decode("utf-8")

