def clickhouse_server_ready() -> bool:
    """Check if ClickHouse is ready and return True/False."""
    if not clickhouse_available():
        return False

    time.sleep(2)
    return True

def exasol_server_ready() -> bool:
    """Check if Exasol is ready and return True/False."""
    global _ready_error

    if not exasol_available():
        return False

    try:
        import pyexasol  # noqa: F401
    except ImportError:
        pytest.skip("pyexasol is not installed")

    deadline = time.time() + EXASOL_READY_TIMEOUT
    while True:
        try:
            _connect().close()
            return True
        except Exception as e:
            _ready_error = str(e)
            if time.time() >= deadline:
                return False
            time.sleep(_READY_INTERVAL)

