def tearDownClass(cls):
        if cls.proc is not None and cls.proc.poll() is None:
            cls.proc.terminate()
            try:
                cls.proc.communicate(timeout=10)
            except subprocess.TimeoutExpired:
                cls.proc.kill()
                cls.proc.communicate(timeout=10)
        cls.proc = None

