def lookup_of() -> Callable[[dict], RemoteLookup]:
    """{provider: {"connect": ..., "models": {id: model()}}} -> a RemoteLookup."""

    def build(providers: dict) -> RemoteLookup:
        return RemoteLookup(
            RemoteManifest.model_validate(
                {
                    "schema_version": 1,
                    "source": "https://models.dev/api.json",
                    "refreshed_at": "2026-09-23",
                    "providers": {
                        name: {
                            "name": name.title(),
                            "doc": None,
                            "connect": spec.get("connect", connect()),
                            "models": spec["models"],
                        }
                        for name, spec in providers.items()
                    },
                }
            )
        )

    return build

def lookup(lookup_of):
    """OpenAI (chat and image), Bedrock (unreachable), Neon (a /responses-only model)."""
    return lookup_of(
        {
            "openai": {"models": {"gpt-5": model(), "gpt-image-1": model(PAINTER)}},
            "amazon-bedrock": {
                "connect": connect("unreachable", "Signs requests with AWS credentials"),
                "models": {"claude": model()},
            },
            "neon": {
                "models": {"gpt-5-pro": model(call={"route": "responses"})},
            },
        }
    )

