def mock_runtime(mock_agent, mock_event_manager):
    """Create a mock runtime that satisfies RuntimeServices protocol."""

    class MockRuntime:
        def __init__(self, agent, event_manager):
            self._agent = agent
            self._events = event_manager

        @property
        def agent(self):
            return self._agent

        @property
        def event_manager(self):
            """Event manager."""
            return self._events

        @property
        def truncation_config(self):
            """Truncation configuration."""
            from nooa.config.truncation_config import DEFAULT_TRUNCATION_CONFIG

            return DEFAULT_TRUNCATION_CONFIG

        async def generate(self, *, tools=None, **kwargs):
            response = MagicMock(content="generated code", reasoning=None, usage={})
            return response, "event_123"

        async def execute_code(self, code, extra_globals=None):
            return None

        async def execute_nested(self, strategy, call):
            """Execute nested strategy."""
            return await strategy.execute(self, call)

        def get_generation_id(self) -> str | None:
            """Get current generation ID."""
            return "mock-generation-id"

        def get_parent_generation_id(self) -> str | None:
            """Get parent generation ID."""
            return None

        async def expand_variables(
            self, text: str, extra_context=None, error_mode: str = "show"
        ) -> str:
            """Mock expand_variables — returns text unchanged."""
            return text

    from unittest.mock import MagicMock

    return MockRuntime(mock_agent, mock_event_manager)

def mock_runtime():
    """Create mock runtime for strategy tests."""
    from nooa.events import ExecutionResult

    class MockRuntime:
        def __init__(self):
            self._agent = MagicMock()
            self._agent.agent_id = "test_agent"
            self._agent.__class__.__name__ = "TestAgent"
            self._agent.event_manager = MagicMock()
            self._agent.events = []
            self._events = MagicMock()
            self._events.add = MagicMock(return_value="event_123")
            self._events.get = MagicMock(return_value=None)
            self._events.update = MagicMock(return_value=True)

        @property
        def agent(self):
            return self._agent

        @property
        def events(self):
            """Event manager."""
            return self._events

        async def generate(self, *, tools=None, output_model=None, tool_choice=None, **kwargs):
            # Mock returning a return_result tool call
            response = MagicMock(
                content="",
                reasoning=None,
                usage={},
                finish_reason="tool_calls",
                tool_calls=[
                    ToolCall(id="call_mock", name="return_result", arguments='{"value": 42}')
                ],
            )
            return response, "event_123"

        async def execute_code(self, code, builtins=None, validate=True, wrap_in_function=False):
            return ExecutionResult(
                stdout="",
                error=None,
                defined_methods={},
            )

        async def execute_nested(self, strategy, call):
            """Execute nested strategy (for @strategy methods)."""
            return await strategy.execute(self, call)

        async def expand_variables(self, template, extra_context=None, error_mode="raise"):
            """Simple variable expansion for templates."""
            context = extra_context or {}
            result = template

            for key, value in context.items():
                result = result.replace(f"{{{key}}}", str(value))

            return result

    return MockRuntime()

def mock_runtime():
