def libs_root(tmp_path: Path, monkeypatch) -> Path:
    """Sandboxed libs root on sys.path; cleans up imports."""
    monkeypatch.syspath_prepend(str(tmp_path))
    for key in [k for k in sys.modules if k.startswith("test_lib_")]:
        del sys.modules[key]
    return tmp_path

