def tmp_file():
    """Write a small file and yield its path; clean up on exit."""
    fd, path = tempfile.mkstemp(prefix="tgtest_", suffix=".txt")
    try:
        with os.fdopen(fd, "wb") as fh:
            fh.write(b"hello cheetahclaws\n")
        yield path
    finally:
        try:
            os.unlink(path)
        except OSError:
            pass

def stub_yfinance(monkeypatch):
    """Stub yfinance.Ticker to return synthetic data."""
    class FakeHist:
        def __init__(self, n=250, drift=0.001):
            import pandas as pd
            self._closes = [100 * (1 + drift) ** i for i in range(n)]
            self._df = pd.DataFrame({
                "Close": self._closes,
            })
            # Pandas index doesn't really matter for our computations
        def __len__(self):
            return len(self._df)
        def __getitem__(self, k):
            return self._df[k]
        @property
        def empty(self):
            return False
        def dropna(self):
            return self

    class FakeTicker:
        def __init__(self, sym, drift=0.001, info_overrides=None):
            self.symbol = sym
            self._drift = drift
            self._info_overrides = info_overrides or {}
        def history(self, period="1y", interval="1d", auto_adjust=False):
            return FakeHist(n=250, drift=self._drift)
        @property
        def info(self):
            base = {
                "trailingPE":      18.0,
                "returnOnEquity":  0.18,
                "debtToEquity":    50.0,
                "operatingMargins": 0.20,
                "marketCap":       500_000_000_000,
                "sector":          "Technology",
            }
            base.update(self._info_overrides)
            return base

    class FakeYF:
        def __init__(self):
            self.calls = 0
        def Ticker(self, sym):
            self.calls += 1
            # Pick drift based on symbol so different tickers score differently
            d = {"AAPL": 0.0015, "MSFT": 0.0010, "GOOG": 0.0008}.get(sym, 0.0005)
            return FakeTicker(sym, drift=d)

    fake = FakeYF()
    import sys
    monkeypatch.setitem(sys.modules, "yfinance", fake)
    return fake

