def lifecycle(participant):
    p, b = participant, participant.bridge
    config = {'agents': {'list': [{'id': 'pixel', 'model': 'local/model'}]},
              'plugins': {'entries': {'pixel-ods': {'enabled': True, 'hooks': {'allowConversationAccess': True}}}}}
    b.before = (json.dumps(config, indent=2) + '\n\n').encode()
    plan = plan_activation(config, revision=1, allow_cloud=False, activation_id=BINDING['activationId'])
    b.after = owner._encoded(plan['document'])
    b.config.write_bytes(b.before)
    b.pid, b.started, b.stopped, b.restarts = 110, 1000, False, 0
    b.boundary, b.definition = 'ProtectSystem=strict\nProtectHome=read-only', '/usr/bin/node pinned-entry'
    b.native_origin, b.native_key = 'http://127.0.0.1:18789', 'not-a-real-key'
    b.nrev, b.live_binding, b.failure = 'e' * 64, None, None
    b.record.update(runtimeCustody='f' * 64, boundary=b.boundary, mode='sandboxed')

    def command(self, args, timeout=20):
        if 'restart' in args:
            self.restarts += 1
            if self.failure == 'restart':
                self.stopped = True
                raise AccessError('host-command-failed')
            self.stopped = False
            if self.failure != 'same-identity': self.pid += 1; self.started += 1000
            self.live_binding = json.loads(self.config.read_bytes())['plugins']['entries']['pixel-ods'].get('config', {}).get('managedProvider')
            return ''
        if 'daemon-reload' in args:
            if self.failure == 'reload': raise AccessError('host-command-failed')
            return ''
        if 'cat' in args:
            text = '# /etc/systemd/system/openclaw-gateway.service\n[Service]\nExecStart=' + self.definition + '\n'
            if p.dropin.exists(): text += '\n# ' + str(p.dropin) + '\n' + p.dropin.read_text()
            return text
        if any('ExecMainStartTimestampMonotonic' in arg for arg in args):
            return f'MainPID={0 if self.stopped else self.pid}\nActiveState={"failed" if self.stopped else "active"}\nExecMainStartTimestampMonotonic={self.started}'
        return self.definition

    def native(self, operation=None, token=None, **kwargs):
        if operation and token != self.token: raise AccessError('native-lease-unconfirmed')
        return {'phase': self.phase, 'active': self.active, 'pid': self.pid, 'revision': self.nrev,
                'proof': {'pid': self.pid, 'mode': 'sandboxed', 'executed': True}}

    def http(self, origin, path, key, payload=None, **kwargs):
        if path == '/health': return {'ok': True}
        result = {'schemaVersion': 1, 'source': 'current-runtime-config', 'pid': self.pid,
                  'runtimeVersion': '2026.6.33', 'revision': self.nrev,
                  'observedAt': datetime.now(timezone.utc).isoformat()}
        if payload['operation'] == 'settings-readback':
            return dict(result, **configured_fields(json.loads(self.config.read_bytes())))
        binding = None if self.failure == 'registration' and self.live_binding else self.live_binding
        return dict(result, source='current-provider-registration', transportVerified=False,
                    registration={'status': 'active' if binding else 'inactive', 'binding': binding})

    b.command, b.native, b.http = MethodType(command, b), MethodType(native, b), MethodType(http, b)
    b.unit_boundary = lambda: b.boundary
    b.settings_source = lambda: 'qualified-owner-data'
    b.provision_probe = lambda: None
    b.stopped_native = lambda token: {'stopped': b.stopped and token == b.token}
    b.record['serviceDefinition'] = service.definition(b, p.dropin)
    atomic_json(b.state / 'transition.json', b.record)
    arm(p)
    return p

def integrated(lifecycle, monkeypatch):
    p, b = lifecycle, lifecycle.bridge
    (b.state / 'transition.json').unlink()
    b.phase = 'idle'
    b.settings_data_dir = b.home / 'data'
    directory = b.settings_data_dir / 'pixel-providers'
    directory.mkdir(parents=True, mode=0o700)
    (directory / '.provider-config.lock').touch(mode=0o600)
    saved = default_config()
    saved.update(enabled=True, revision=1)
    saved['providers'] = [dict(id='leader', label='Tower', kind='local', baseUrl='http://127.0.0.1:12001/v1',
        model='qwen', contextWindow=32768, maxOutputTokens=4096, supportsTools=True,
        supportsVision=False, reasoning=False, credentialRef=None, enabled=True)]
    saved['roles']['leader'] = 'leader'
    atomic_json(directory / 'provider-config.json', saved)
    b.pending = lambda: json.loads((b.state / 'transition.json').read_text()) if (b.state / 'transition.json').exists() else None
    b.locked = contextlib.nullcontext
    b.inspect = lambda: {'revision': digest([b.pid, b.pending(), b.phase]), 'busy': bool(b.active or b.streams),
        'configured_mode': 'sandboxed', 'runtime_verified': True, '_edge': {'revision': b.nrev}}
    original_read = c.settings._read
    monkeypatch.setattr(c.settings, '_read', lambda path, uid, maximum=1024*1024:
                        original_read(path, os.getuid() if uid == 0 else uid, maximum))
    monkeypatch.setattr(c, '_parents', service_environment._parents)
    monkeypatch.setattr(c, 'ServiceEnvironment', lambda bridge: p)

    class Runtime:
        def __init__(self, bridge): pass
        def qualify(self): return 'f' * 64
        def verify_process(self):
            if b.failure == 'process': raise AccessError('provider-runtime-process-unqualified')
        def deployment(self, binding, directory):
            return deployment(binding, '/opt/ods/source', '/usr/bin/python3', str(directory), True), required_policy(), self.qualify()
    monkeypatch.setattr(c, 'RuntimeCustody', Runtime)
    native = b.native

    def native_lease(self, operation=None, token=None, **kwargs):
        if operation == 'acquire' and self.phase == 'idle': self.token, self.phase = token, 'held'
        if operation == 'release': self.phase = 'idle'
        return native(operation, token, **kwargs)

    def edge(self, operation=None, token=None, revision=None):
        if operation in ('acquire', 'recover'):
            if self.phase == 'idle': self.token, self.phase = token, 'held'
            if token != self.token: raise AccessError('foreign-edge-token')
        if operation == 'release':
            if self.failure == 'edge-release': raise AccessError('release-failed')
            self.phase = 'idle'
        return {'phase': self.phase, 'revision': self.nrev, 'streams': self.streams}

    def worker(self, operation, **kwargs):
        common = dict(state_dir=str(b.home / '.openclaw/.ods-access-mode'))
        if operation == 'provider-status': return owner.provider_status(str(b.config), **common)
        common.update(transaction_id=kwargs['transaction_id'], expected_config_sha256=kwargs['config_hash'],
            validate_config=lambda path: bool(json.loads(Path(path).read_bytes())),
            check_no_active_run=kwargs['busy'], activate=kwargs['activate_provider'])
        if operation == 'provider-change':
            result = owner.change_provider(str(b.config), binding=kwargs['binding'],
                                           expected_projection=kwargs['expected_projection'], **common)
            if self.failure == 'lost-reply': raise AccessError('owner-worker-timeout')
            return result
        return owner.recover_provider(str(b.config), **common)
    b.native, b.edge, b.worker = MethodType(native_lease, b), MethodType(edge, b), MethodType(worker, b)
    b.saved, b.directory = saved, directory
    return p

def provider_stack(actual_stack, monkeypatch):
    import pixel_access_client
    from pixel_provider import host_api
    client, agent, handler = actual_stack
    client.app.include_router(pixel_providers.router)
    monkeypatch.setattr(host_api.platform, 'system', lambda: 'Linux')
    calls = []
    state = {'status': 'inactive', 'revision': 'a' * 64, 'providerRevision': 3, 'binding': None,
             'pending': False, 'registrationVerified': True, 'transportVerified': False,
             'lastVerifiedAt': '2026-09-09T18:01:25.584Z'}
    def control(operation, body=None, **kwargs):
        calls.append((operation, body, kwargs))
        if operation == 'provider-status': return 200, copy.deepcopy(state)
        binding = BINDING if body['operation'] == 'apply' else None
        state.update(status='applied' if binding else 'inactive', binding=binding, pending=False)
        return 200, {'outcome': 'rolled-back' if body['operation'] == 'recover' else 'applied',
                     'binding': binding, 'registrationVerified': True, 'transportVerified': False}
    monkeypatch.setattr(pixel_access_client, 'request_access', control)
    return client, agent, handler, calls, state

