            username="cg_owner", password="x", email="cgo@test.com"
        )
        self.other_owner = User.objects.create_user(
            username="cg_other_owner", password="x", email="cgoo@test.com"
        )
        self.viewer = User.objects.create_user(
            username="cg_viewer", password="x", email="cgv@test.com"
        )
        self.stranger = User.objects.create_user(
            username="cg_stranger", password="x", email="cgstr@test.com"
        )

        # Member corpora with distinct visibility profiles.
        self.owner_corpus = Corpus.objects.create(
            title="Owner Corpus", creator=self.owner, is_public=False
        )
        self.foreign_corpus = Corpus.objects.create(
            title="Foreign Corpus", creator=self.other_owner, is_public=False
        )
        self.public_corpus = Corpus.objects.create(
            title="Public Corpus", creator=self.other_owner, is_public=True
        )
        # ``viewer`` can read the group and the foreign corpus, nothing else.
        set_permissions_for_obj_to_user(
            self.viewer, self.foreign_corpus, [PermissionTypes.READ]
        )

        self.group = CorpusGroup.objects.create(
            title="Mixed Group", creator=self.owner, is_public=False
        )
        # Membership is set directly at the ORM level to simulate drift:
        # a corpus can be in a group even when a given caller can't see it.
        self.group.corpora.set(
            [self.owner_corpus, self.foreign_corpus, self.public_corpus]
        )
        set_permissions_for_obj_to_user(self.viewer, self.group, [PermissionTypes.READ])

