        lavafuncs.lava_data = None
        ilapfuncs.identifiers.clear()
        ilapfuncs.identifiers.update(self.saved_identifiers)
        Context.clear()
        Context.set_output_params(None)
        shutil.rmtree(self.tmpdir, ignore_errors=True)

