def _reset_tool_prefetches() -> Iterator[None]:
    """Forget prefetched scans and analyses without importing their tools eagerly.

    The registries are process-global, so a prefetch one test started would
    otherwise answer a later test's tool call on the same xdist worker.
    """

    def reset() -> None:
        for name, reset_name in (
            ("tools.system.workspace_git_scan.prefetch", "reset_scan_prefetch"),
            ("integrations.github.tools.ci_analytics.prefetch", "reset_analysis_prefetch"),
        ):
            module = sys.modules.get(name)
            if module is not None:
                getattr(module, reset_name)()

    reset()
    try:
        yield
    finally:
        reset()

def snapshots(monkeypatch: pytest.MonkeyPatch) -> list[datetime]:
    """The ``now`` of every snapshot the tool writes."""
    written: list[datetime] = []
    real_write = tool_module.write_snapshot

    def write(root: Path, owner: str, repo: str, now: datetime, payload: dict[str, Any]) -> Path:
        written.append(now)
        return real_write(root, owner, repo, now, payload)

    monkeypatch.setattr(tool_module, "write_snapshot", write)
    return written

def run_errors(monkeypatch: pytest.MonkeyPatch) -> list[Exception]:
    reported: list[Exception] = []

    def report(exc: Exception, **_kwargs: Any) -> None:
        reported.append(exc)

    monkeypatch.setattr(tool_module, "report_run_error", report)
    return reported

