def monthly():
    """Twelve years of monthly returns: a benchmark and three assets with regime-dependent betas."""
    rng = np.random.default_rng(20260926)
    b = 0.005 + 0.04 * rng.standard_normal(144)
    tail = b < np.quantile(b, 0.16)
    assets = {'A': 0.3 * b + 0.02 * rng.standard_normal(144),
              'B': np.where(tail, -1.5, 0.2) * b + 0.03 * rng.standard_normal(144),
              'C': -0.2 * b + 0.025 * rng.standard_normal(144)}
    index = pd.date_range('2012-01-31', periods=144, freq='ME')
    return pd.DataFrame({'BM': b, **assets}, index=index)

def sampled():
    """Quarterly returns of a clean synthetic panel with the one-sigma regimes of its benchmark."""
    universe = generate_synthetic_universe(start='2005-01-03', end='2025-12-31', apply_quirks=False)
    prices = pd.concat([universe.benchmark_prices, universe.prices], axis=1)[ASSETS]
    return BenchmarkReturnsQuantilesRegime(freq='QE').compute_sampled_returns_with_regime_id(
        prices=prices, benchmark='SBM_6040')

def daily_returns() -> pd.Series:
    """daily simple returns with no leading missing row, as pyfolio and QuantStats take them."""
    universe = generate_synthetic_universe(start='2018-01-02', end='2025-12-31', seed=20260725,
                                           apply_quirks=False)
    return universe.prices['SEQ_US'].pct_change().dropna().rename('strategy')

