def worker_guard(api: Api):
    """Stop every worker this test started, even if it failed midway."""
    before = {w["id"] for w in api.get("/api/worker/status").get("workers", [])}
    yield before
    after = api.get("/api/worker/status").get("workers", [])
    for w in after:
        if w["id"] not in before and w.get("status") in (
            "starting",
            "running",
            "stopping",
            "paused",
            "quota_paused",
        ):
            api.post("/api/worker/stop", {"worker_id": w["id"]})

def matrix(api):
    """Function-scoped on purpose: `api` re-points at whatever binary the
    dashboard is focused on right now, and focus is server state that other
    tests change. A module-scoped cache here would pin one binary's matrix
    across a focus switch."""
    return api.get("/api/conformance/matrix")

def ground_truth() -> dict[str, Any]:
    path = BENCHMARK_DIR / "ground_truth.json"
    if not path.is_file():
        pytest.skip(f"{path} missing; run fun-doc/benchmark/extract_truth.py")
    return json.loads(path.read_text(encoding="utf-8"))

def authored_functions(ground_truth) -> list[str]:
    """The hand-written functions -- the only ones with a known right answer.

    This list IS the library positive control: whatever else the run claims
    as CRT, none of these may be among it.
    """
    return sorted(ground_truth.get("functions", {}))

def baseline_run() -> dict[str, Any] | None:
    """`runs/latest.json`, or None on a machine that has never run it."""
    path = BENCHMARK_DIR / "runs" / "latest.json"
    if not path.is_file():
        return None
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None

