def origin_consumer() -> Any:
    """Register a recording consumer; restore whatever was registered before."""
    previous = origin_adapters._origin_consumer
    consumer = _RecordingOriginConsumer()
    origin_adapters.register_pending_origin_consumer(consumer)
    try:
        yield consumer
    finally:
        if previous is None:
            origin_adapters.reset_origin_consumer()
        else:
            origin_adapters.register_pending_origin_consumer(previous)

def probing_consumer(tmp_path: Path) -> Iterator[_CommitStateProbingConsumer]:
    previous = origin_adapters._origin_consumer
    consumer = _CommitStateProbingConsumer(tmp_path / "repo")
    origin_adapters.register_pending_origin_consumer(consumer)
    try:
        yield consumer
    finally:
        if previous is None:
            origin_adapters.reset_origin_consumer()
        else:
            origin_adapters.register_pending_origin_consumer(previous)

def spies(monkeypatch: pytest.MonkeyPatch) -> _Spies:
    """Install the legacy-helper spy and an apply-seam counter on the real flow."""
    counters = _Spies()
    monkeypatch.setenv("CI", "1")

    if hasattr(upgrade_module, _LEGACY_HELPER):

        def _legacy_spy(*args: Any, **kwargs: Any) -> None:
            counters.legacy_calls += 1

        monkeypatch.setattr(upgrade_module, _LEGACY_HELPER, _legacy_spy)

    real_apply = getattr(assessment, _APPLY)

    def _counting_apply(*args: Any, **kwargs: Any) -> Any:
        counters.apply_calls += 1
        return real_apply(*args, **kwargs)

    monkeypatch.setattr(assessment, _APPLY, _counting_apply)
    return counters

