        monkeypatch.setattr(
            'bisheng.database.models.audit_log.bypass_tenant_filter',
            _spy,
        )
        monkeypatch.setattr(
            'bisheng.database.models.audit_log.get_sync_db_session',
            _fake_get_sync,
        )
        monkeypatch.setattr(
            'bisheng.api.services.audit_log.resp_200',
            lambda data=None: {'data': data},
        )
        return calls

def listener_env(self, monkeypatch, session):
        """Per-instance fake F013 listener + DAO session monkeypatch.

        Returns a ``(session, seed)`` tuple. ``seed`` runs ``_insert_audit``
        calls inside the real ``bypass_tenant_filter`` so the inserts'
        post-commit ``session.refresh()`` SELECT isn't pinned by the
        listener (which would otherwise hide rows whose ``tenant_id``
        doesn't equal ``current_tenant_id``).
        """
        from sqlalchemy import event
        from bisheng.core.context.tenant import (
            bypass_tenant_filter as real_bypass,
            current_tenant_id,
            get_current_tenant_id,
            is_tenant_filter_bypassed,
        )

        @event.listens_for(session, 'do_orm_execute')
        def _fake_listener(state):
            if is_tenant_filter_bypassed():
                return
            if not state.is_select:
                return
            tid = get_current_tenant_id()
            if tid is None:
                return
            try:
                state.statement = state.statement.where(
                    AuditLog.__table__.c.tenant_id == tid
                )
            except Exception:
                return

        # Set ROOT as the admin's leaf tenant to mimic production.
        token = current_tenant_id.set(1)

        @contextmanager
        def _fake_get_sync():
            yield session

        monkeypatch.setattr(
            'bisheng.database.models.audit_log.get_sync_db_session',
            _fake_get_sync,
        )
        monkeypatch.setattr(
            'bisheng.api.services.audit_log.resp_200',
            lambda data=None: {'data': data},
        )

        def seed(*entries):
            with real_bypass():
                for kwargs in entries:
                    _insert_audit(session, **kwargs)

        try:
            yield session, seed
        finally:
            current_tenant_id.reset(token)

def patches(monkeypatch):
    """Wire DAO / session / sync_user mocks for the local-primary swap path."""
    sync_mock = AsyncMock(name='sync_user')
    monkeypatch.setattr(sync_module.UserTenantSyncService, 'sync_user', sync_mock)

    dept_execute = AsyncMock(name='DepartmentChangeHandler.execute_async')
    monkeypatch.setattr(
        ds_module.DepartmentChangeHandler, 'execute_async', dept_execute,
    )
    admin_grant_delete = AsyncMock(name='DepartmentAdminGrantDao.adelete')
    monkeypatch.setattr(
        ds_module.DepartmentAdminGrantDao, 'adelete', admin_grant_delete,
    )

    session_calls = {
        'exec': [], 'add': [], 'delete': [], 'commit': 0,
        # ``rows_for_select`` controls what the next ``session.exec(select(UserDepartment...))``
        # returns. Tests set it once before driving the service.
        'rows_for_select': [],
    }

    class _FakeExecResult:
        def __init__(self, rows):
            self._rows = list(rows)

        def all(self):
            return list(self._rows)

        def first(self):
            return self._rows[0] if self._rows else None

    class _FakeSession:
        async def exec(self, stmt):
            session_calls['exec'].append(stmt)
            return _FakeExecResult(session_calls['rows_for_select'])

        def add(self, obj):
            session_calls['add'].append(obj)

        async def delete(self, obj):
            session_calls['delete'].append(obj)

        async def commit(self):
            session_calls['commit'] += 1

    @asynccontextmanager
    async def _fake_get_session():
        yield _FakeSession()

    monkeypatch.setattr(ds_module, 'get_async_db_session', _fake_get_session)

    return SimpleNamespace(
        sync=sync_mock,
        dept_execute=dept_execute,
        admin_grant_delete=admin_grant_delete,
        session_calls=session_calls,
    )

