def temp_dir():
    """Create a temporary directory for test files."""
    temp_path = tempfile.mkdtemp()
    yield temp_path
    # Windows-safe cleanup
    import time
    for _ in range(3):
        try:
            shutil.rmtree(temp_path)
            return
        except PermissionError:
            time.sleep(0.1)
        except Exception:
            return

