def engine():
    for candidate in (LiveEngine, DockerEngine):
        if not candidate.available():
            continue
        instance = candidate()
        try:
            instance.start()
        except Exception as exc:  # the next candidate, or no engine at all
            instance.stop()
            pytest.skip(f"{candidate.kind} ClickHouse unavailable: {exc!r}")
        try:
            for statement in schema_statements():
                instance.execute(statement)
            instance.execute("SYSTEM STOP MERGES spans")
            for statement in insert_statements():
                instance.execute(statement)
            yield instance
        finally:
            instance.stop()
        return
    pytest.skip(
        "no ClickHouse engine: set FI_LIVE_CH_TESTS=1 for a loopback CH 25.3, "
        f"or make the {DOCKER_IMAGE} image available locally"
    )

def annotation_label_type(monkeypatch):
    """Serve one annotation label type without touching PostgreSQL."""

    def _serve(label_type):
        monkeypatch.setattr(
            dashboard_builder,
            "resolve_annotation_label_output_type",
            lambda label_id, organization_id=None: (
                label_type if label_id == LABEL_ID else None
            ),
        )

    return _serve

def eval_output_type(monkeypatch):
    """Serve one eval template identity and output type without PostgreSQL."""

    def _serve(output_type):
        monkeypatch.setattr(
            DashboardQueryBuilder,
            "_resolve_eval_template_identity",
            lambda self, payload, fallback: fallback,
        )
        monkeypatch.setattr(
            dashboard_builder,
            "resolve_eval_filter_metadata",
            lambda eval_id, project_ids: EvalFilterMetadata(
                config_ids=(eval_id,), output_type=output_type
            ),
        )

    return _serve

def ch_database():
    database = f"test_session_rollup_{uuid.uuid4().hex}"
    _require_safe_ch25_test_target(host=CH_HOST, database=database)
    admin = _ch_client(database="default")
    created = False
    try:
        try:
            admin.execute("SELECT 1")
        except Exception as exc:
            pytest.skip(
                f"CH25 is not reachable on {CH_HOST}:{CH_NATIVE_PORT} ({exc!r})"
            )
        admin.execute(f"CREATE DATABASE {database}")
        created = True
        yield database
    finally:
        try:
            if created:
                # The target is the unguessable database created above; no
                # shared schema object is touched during cleanup.
                admin.execute(f"DROP DATABASE IF EXISTS {database} SYNC")
        finally:
            admin.disconnect()

def scheduled(monkeypatch):
    calls = []

    def _read_or_schedule(namespace, identity, **kwargs):
        calls.append((namespace, identity, kwargs))
        if not kwargs.get("refresh"):
            # A cold cache probe. Returning the pending envelope here would
            # short-circuit every case below before any read is routed.
            return None
        return dict(kwargs["pending_payload"])

    monkeypatch.setattr(
        graph_dispatch,
        "read_or_schedule_exact_snapshot",
        _read_or_schedule,
    )
    return calls

