def typed_graph():
    rng = np.random.default_rng(1)
    n_nodes, deg = 2000, 6
    m = n_nodes * deg
    edf = pd.DataFrame({
        "src": rng.integers(0, n_nodes, m),
        "dst": rng.integers(0, n_nodes, m),
        "etype": rng.integers(0, 3, m),
    })
    ndf = pd.DataFrame({"id": np.arange(n_nodes)})
    return graphistry.nodes(ndf, "id").edges(edf, "src", "dst")

def _restore_lean_env():
    """Keep GFQL_LEAN_COMBINE hermetic across tests."""
    prev = os.environ.get('GFQL_LEAN_COMBINE')
    yield
    if prev is None:
        os.environ.pop('GFQL_LEAN_COMBINE', None)
    else:
        os.environ['GFQL_LEAN_COMBINE'] = prev

def blocked(monkeypatch):
    """Make a module unimportable for the duration of one test."""
    def _block(name: str) -> None:
        root = name.split(".")[0]
        for key in [k for k in sys.modules if k == root or k.startswith(root + ".")]:
            monkeypatch.delitem(sys.modules, key, raising=False)
        monkeypatch.setitem(sys.modules, root, None)
    return _block

