def tearDown(self):
        shutil.rmtree(self.target, ignore_errors=True)
        for mod in list(sys.modules):
            if mod == _DOWNLOAD_PACKAGE or mod.startswith(_DOWNLOAD_PACKAGE + "."):
                del sys.modules[mod]
        if self.target in sys.path:
            sys.path.remove(self.target)

