def project(tmp_path):
    """A project shipping a real ``tests/fixtures/`` module, plus a store."""
    proj = tmp_path / "proj"
    (proj / "tests" / "fixtures").mkdir(parents=True)
    store = tmp_path / "store"
    store.mkdir()
    (proj / "main.py").write_text("def main():\n    return 1\n")
    (proj / FIXTURE_REL).write_text(
        "class FakeServer:\n    def serve(self):\n        return 3\n"
    )
    for args in (
        ("init", "-q"),
        ("config", "user.email", "repro@example.invalid"),
        ("config", "user.name", "repro"),
        ("add", "-A"),
        ("commit", "-q", "-m", "A"),
    ):
        subprocess.run(["git", *args], cwd=str(proj), check=True, capture_output=True)

    class Project:
        path = proj
        store_path = str(store)

        @staticmethod
        def declare(**keys):
            (proj / ".jcodemunch.jsonc").write_text(json.dumps(keys, indent=2))
            cfg.load_project_config(str(proj))

        @staticmethod
        def index():
            return index_folder(
                path=str(proj), identity_mode="local", use_ai_summaries=False,
                storage_path=str(store),
            )

    return Project

def embedded(tmp_path, monkeypatch):
    """An indexed repo plus helpers to embed it under a named fake provider."""
    src = tmp_path / "src"
    src.mkdir()
    store_dir = tmp_path / "store"
    store_dir.mkdir()
    for i in range(5):
        (src / f"m{i}.py").write_text(f"def handler_{i}():\n    return {i}\n")
    result = index_folder(
        str(src), use_ai_summaries=False, storage_path=str(store_dir),
    )
    assert result["success"] is True
    repo_id = result["repo"]
    owner, name = repo_id.split("/", 1)
    index_store = IndexStore(base_path=str(store_dir))
    db_path = index_store._sqlite._db_path(owner, name)

    class Harness:
        repo = repo_id
        path = src
        store_path = str(store_dir)
        db = db_path

        @staticmethod
        def embed(model, width, **kwargs):
            monkeypatch.setattr(
                er, "_detect_provider", lambda: ("fake_provider", model)
            )
            monkeypatch.setattr(er, "embed_texts", _fixed_width(width))
            return er.embed_repo(
                repo=repo_id, storage_path=str(store_dir), **kwargs
            )

        @staticmethod
        def store():
            return EmbeddingStore(db_path)

        @staticmethod
        def widths():
            counts = {}
            for _sid, blob in EmbeddingStore(db_path).iter_raw():
                w = len(blob) // 4
                counts[w] = counts.get(w, 0) + 1
            return counts

        @staticmethod
        def add_symbol(n):
            (src / f"extra{n}.py").write_text(f"def extra_{n}():\n    return {n}\n")
            index_folder(
                str(src), use_ai_summaries=False, storage_path=str(store_dir),
            )

    return Harness

