def repo(tmp_path):
    work = tmp_path / "demo"
    work.mkdir()
    store = tmp_path / "store"
    store.mkdir()
    _git(work, "init", "-q")
    _git(work, "config", "user.email", "repro@example.invalid")
    _git(work, "config", "user.name", "repro")
    _git(work, "remote", "add", "origin", "https://github.com/acme/demo.git")
    (work / "main.py").write_text("def main():\n    return 1\n")
    (work / "pkg").mkdir()
    (work / "pkg" / "mod.py").write_text("def mod():\n    return 2\n")
    _git(work, "add", "-A")
    _git(work, "commit", "-q", "-m", "A")

    class Repo:
        path = work
        store_path = str(store)

        @staticmethod
        def index(**kwargs):
            return index_folder(
                str(work), use_ai_summaries=False, storage_path=str(store),
                identity_mode="git", **kwargs,
            )

        @staticmethod
        def index_subdir(rel, **kwargs):
            return index_folder(
                str(work / rel), use_ai_summaries=False, storage_path=str(store),
                identity_mode="git", **kwargs,
            )

    return Repo

def spy(monkeypatch):
    """Count packages_distributions() calls without changing what it returns."""
    calls = {"n": 0, "returns": {}}

    def fake_packages_distributions():
        calls["n"] += 1
        return calls["returns"]

    fake_meta = types.ModuleType("importlib.metadata")
    fake_meta.packages_distributions = fake_packages_distributions
    fake_meta.PackageNotFoundError = LookupError

    def set_official(dist_or_exc):
        def distribution(name):
            if isinstance(dist_or_exc, Exception):
                raise dist_or_exc
            return dist_or_exc
        fake_meta.distribution = distribution

    set_official(LookupError("not installed"))
    calls["set_official"] = set_official
    monkeypatch.setitem(sys.modules, "importlib.metadata", fake_meta)
    return calls

