def existing_file() -> Generator[str, None, None]:
    """Create a temporary file that already exists."""
    with tempfile.NamedTemporaryFile(delete=False, suffix=".txt") as f:
        f.write(b"existing content")
        path = f.name

    try:
        yield path
    finally:
        if os.path.exists(path):
            os.unlink(path)

