def parked_threads():
    release = threading.Event()
    threads = [threading.Thread(target=release.wait, args=(30,), daemon=True) for _ in range(120)]
    for thread in threads:
        thread.start()
    yield threads
    release.set()
    for thread in threads:
        thread.join(5)

