        # Reset module-level thread-local connections between tests.
        tl = getattr(beam_module, "_thread_local", None)
        if tl is not None and hasattr(tl, "conn") and tl.conn is not None:
            try:
                tl.conn.close()
            except Exception:
                pass
            tl.conn = None
            if hasattr(tl, "db_path"):
                tl.db_path = None

