def _make_handle(self) -> Callable[..., SoftwareKeyHandle]:
        from cryptography.hazmat.primitives.asymmetric import ed25519

        def factory(
            key_id: str = "test-key",
            key_origin: KeyOrigin = KeyOrigin.LOCAL,
            expires_at: datetime | None = None,
        ) -> SoftwareKeyHandle:
            private_key = ed25519.Ed25519PrivateKey.generate()
            return SoftwareKeyHandle(
                key_id=key_id,
                key_origin=key_origin,
                private_key=private_key,
                expires_at=expires_at,
            )

        return factory

def _local_handle(self) -> SoftwareKeyHandle:
        from cryptography.hazmat.primitives.asymmetric import ed25519

        pk = ed25519.Ed25519PrivateKey.generate()
        return SoftwareKeyHandle(
            key_id="local-key",
            key_origin=KeyOrigin.LOCAL,
            private_key=pk,
        )

def _skr_handle(self) -> SoftwareKeyHandle:
        from cryptography.hazmat.primitives.asymmetric import ed25519

        pk = ed25519.Ed25519PrivateKey.generate()
        return SoftwareKeyHandle(
            key_id="skr-key",
            key_origin=KeyOrigin.SKR,
            private_key=pk,
        )

def authorizer_key(self):
        try:
            from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey

            key = Ed25519PrivateKey.generate()
            return key.private_bytes_raw().hex(), key.public_key().public_bytes_raw().hex()
        except ImportError as exc:
            raise pytest.skip.Exception("cryptography not installed") from exc

def authorizer_key():
    try:
        from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey

        key = Ed25519PrivateKey.generate()
        return key.private_bytes_raw().hex(), key.public_key().public_bytes_raw().hex()
    except ImportError as exc:
        raise pytest.skip.Exception("cryptography not installed") from exc

def ed25519_keys():
    try:
        from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey

        signer = Ed25519PrivateKey.generate()
        authorizer = Ed25519PrivateKey.generate()
        return (
            signer.private_bytes_raw().hex(),
            authorizer.private_bytes_raw().hex(),
            authorizer.public_key().public_bytes_raw().hex(),
        )
