def handler_no_token(mock_mass: MagicMock) -> DirectConnectionHandler:
    """Return a handler with no initial access token (first-time OAuth flow)."""
    _handler_no_token_tokens.clear()

    def on_token(t: str) -> None:
        _handler_no_token_tokens.append(t)

    return DirectConnectionHandler(
        mass=mock_mass,
        user_id="test_user",
        access_token="",
        client_secret=TEST_CLIENT_SECRET,
        exposed_ids=None,
        on_token_created=on_token,
    )

def device_info() -> YnisonDeviceInfo:
    """Create test device info."""
    return YnisonDeviceInfo(
        device_id="test-device-id",
        title="Test Device",
    )

def mock_state_callback() -> AsyncMock:
    """Create a mock callback for state updates."""
    return AsyncMock()

def client(
