def client() -> AsyncMock:
    """Return a mocked Pocket Casts API client."""
    return AsyncMock()

def _instant_launch_timeout(monkeypatch: pytest.MonkeyPatch) -> None:
    """Keep the unanswered-launch cases from waiting out the real timeout."""
    monkeypatch.setattr("music_assistant.providers.chromecast.player.APP_LAUNCH_TIMEOUT", 0.01)

def provider(mass_mock: MagicMock) -> MammamiradioProvider:
    """Return a configured MammamiradioProvider for unit testing."""
    manifest = MagicMock()
    manifest.domain = "mammamiradio"
    manifest.name = "mammamiradio"

    config = MagicMock()
    config.instance_id = "mammamiradio_test"
    config.values = {}

    def _get_value(key: str, default: Any = None) -> Any:
        if key == CONF_MAMMAMIRADIO_URL:
            return "legacy-config-must-not-be-used"
        if key == "log_level":
            return "GLOBAL"
        return default

    config.get_value.side_effect = _get_value

    return MammamiradioProvider(mass_mock, manifest, config, SUPPORTED_FEATURES)

def providers() -> dict[str, Mock]:
    """One mocked OpenSonicProvider per instance."""
    provs = {INSTANCE_A: Mock(spec=OpenSonicProvider), INSTANCE_B: Mock(spec=OpenSonicProvider)}
    for prov in provs.values():
        prov.conn = Mock()
        prov.conn.scrobble = AsyncMock()
    return provs

def handler(mass: Mock) -> SubsonicScrobbleEventHandler:
    """Event handler under test, with default plugin config."""
    config = Mock()
    config.get_value.side_effect = lambda _key, default=None: default
    return SubsonicScrobbleEventHandler(mass, logging.getLogger(__name__), config)

def responses() -> list[tuple[int, Any, dict[str, str]]]:
    """Supply catalogue responses in order, repeating the last response."""
    return [(200, {"id": int(TRACK_ID), "isrc": ISRC}, {})]

def requests() -> list[dict[str, Any]]:
    """Collect requests received by the catalogue server."""
    return []

