def _clean(monkeypatch):
    monkeypatch.setattr(terminal.os, "killpg", lambda *a, **k: None)
    yield
    with terminal._LOCK:
        sids = list(terminal._TERMINALS)
    for sid in sids:
        try:
            terminal.close_terminal(sid)
        except Exception:
            pass

def tokenizer():
    """Create a tokenizer for testing."""
    return AutoTokenizer.from_pretrained("gpt2")

def disable_wandb(monkeypatch):
    """Disable WANDB logging during tests."""
    monkeypatch.setenv("WANDB_MODE", "disabled")

def solver_instance() -> Any:
    """Loads the user's 'Solver' class from solver.py."""
    if not SOLVER_PATH.exists():
        pytest.fail(f"Solver file not found at {SOLVER_PATH}")

    spec = importlib.util.spec_from_file_location("solver", SOLVER_PATH)
    solver_module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(solver_module)
    return solver_module.Solver()

async def fake_llm_server(request):
    """A pytest fixture to run a fake LLM server and capture requests."""
    # Get the use_tool_calls parameter from the test (defaults to True)
    use_tool_calls = getattr(request, "param", True)
    call_count = {"count": 0}

    async def fake_openai_handler(http_request):
        """Fake OpenAI API endpoint that returns deterministic responses."""
        request_data = await http_request.json()

        # Increment call count
        call_count["count"] += 1

        # Get the model from the request
        model = request_data.get("model", "gpt-4")

        print(
            f"[FAKE SERVER] Received call #{call_count['count']} for model: {model} (tool_calls={'enabled' if use_tool_calls else 'disabled'})"
        )

        if use_tool_calls:
            # Function calling enabled - use tool_calls format
            # First call: Create the hello.txt file
            if call_count["count"] == 1:
                response = {
                    "id": "chatcmpl-fake-1",
                    "object": "chat.completion",
                    "created": 1234567890,
                    "model": model,
                    "choices": [
                        {
                            "index": 0,
                            "message": {
                                "role": "assistant",
                                "content": None,
                                "tool_calls": [
                                    {
                                        "id": "call_fake_1",
                                        "type": "function",
                                        "function": {
                                            "name": "str_replace_editor",
                                            "arguments": json.dumps(
                                                {
                                                    "command": "create",
                                                    "path": "/app/hello.txt",
                                                    "file_text": "Hello, world!",
                                                    "security_risk": "LOW",
                                                }
                                            ),
                                        },
                                    }
                                ],
                            },
                            "finish_reason": "tool_calls",
                        }
                    ],
                    "usage": {
                        "prompt_tokens": 100,
                        "completion_tokens": 50,
                        "total_tokens": 150,
                    },
                }
            # Second call: Finish the task
            elif call_count["count"] == 2:
                response = {
                    "id": "chatcmpl-fake-2",
                    "object": "chat.completion",
                    "created": 1234567891,
                    "model": model,
                    "choices": [
                        {
                            "index": 0,
                            "message": {
                                "role": "assistant",
                                "content": None,
                                "tool_calls": [
                                    {
                                        "id": "call_fake_2",
                                        "type": "function",
                                        "function": {
                                            "name": "finish",
                                            "arguments": json.dumps(
                                                {"message": "Task complete. Created /app/hello.txt with 'Hello, world!'"}
                                            ),
                                        },
                                    }
                                ],
                            },
                            "finish_reason": "tool_calls",
                        }
                    ],
                    "usage": {
                        "prompt_tokens": 120,
                        "completion_tokens": 30,
                        "total_tokens": 150,
                    },
                }
            else:
                # Fallback for any additional calls - return a simple text response
                response = {
                    "id": f"chatcmpl-fake-{call_count['count']}",
                    "object": "chat.completion",
                    "created": 1234567890 + call_count["count"],
                    "model": model,
                    "choices": [
                        {
                            "index": 0,
                            "message": {
                                "role": "assistant",
                                "content": "Task already completed.",
                            },
                            "finish_reason": "stop",
                        }
                    ],
                    "usage": {
                        "prompt_tokens": 100,
                        "completion_tokens": 10,
                        "total_tokens": 110,
                    },
                }
        else:
            # Function calling disabled - use text-based tool invocation with proper XML format
            # First call: Create the hello.txt file
            if call_count["count"] == 1:
                response = {
                    "id": "chatcmpl-fake-1",
                    "object": "chat.completion",
                    "created": 1234567890,
                    "model": model,
                    "choices": [
                        {
                            "index": 0,
                            "message": {
                                "role": "assistant",
                                "content": (
                                    "<function=execute_bash>\n<parameter=command>cat > /app/hello.txt << 'EOF'\nHello, world!\nEOF\n</parameter>\n<parameter=security_risk>LOW</parameter>\n</function>"
                                ),
                            },
                            "finish_reason": "stop",
                        }
                    ],
                    "usage": {
                        "prompt_tokens": 100,
                        "completion_tokens": 50,
                        "total_tokens": 150,
                    },
                }
            # Second call: Finish the task
            elif call_count["count"] == 2:
                response = {
                    "id": "chatcmpl-fake-2",
                    "object": "chat.completion",
                    "created": 1234567891,
                    "model": model,
                    "choices": [
                        {
                            "index": 0,
                            "message": {
                                "role": "assistant",
                                "content": (
                                    "<function=finish>\n<parameter=message>Task complete. Created /app/hello.txt with 'Hello, world!'</parameter>\n</function>"
                                ),
                            },
                            "finish_reason": "stop",
                        }
                    ],
                    "usage": {
                        "prompt_tokens": 120,
                        "completion_tokens": 30,
                        "total_tokens": 150,
                    },
                }
            else:
                # Fallback for any additional calls - return a simple text response
                response = {
                    "id": f"chatcmpl-fake-{call_count['count']}",
                    "object": "chat.completion",
                    "created": 1234567890 + call_count["count"],
                    "model": model,
                    "choices": [
                        {
                            "index": 0,
                            "message": {
                                "role": "assistant",
                                "content": "Task already completed.",
                            },
                            "finish_reason": "stop",
                        }
                    ],
                    "usage": {
                        "prompt_tokens": 100,
                        "completion_tokens": 10,
                        "total_tokens": 110,
                    },
                }

        return web.json_response(response)

    app = web.Application()
    app.router.add_post("/v1/chat/completions", fake_openai_handler)
    runner = web.AppRunner(app)
    await runner.setup()
    # Listen on all interfaces (0.0.0.0) so Docker containers can access it
    site = web.TCPSite(runner, "0.0.0.0", 0)  # Use port 0 for a random available port
    await site.start()
    port = site._server.sockets[0].getsockname()[1]

    def get_call_count():
        return call_count["count"]

    print(f"\n[FAKE SERVER] Started on http://localhost:{port}/v1")

    yield {
        "port": port,
        "get_call_count": get_call_count,
        "use_tool_calls": use_tool_calls,
    }

    await runner.cleanup()
    print("[FAKE SERVER] Stopped")

async def fake_llm_server_with_summarization():
    """A pytest fixture to run a fake LLM server that simulates context summarization.

    This server will:
    1. Return responses that build up conversation history
    2. Trigger context length exceeded error to force summarization
    3. Handle summarization requests (summary generation, questions, answers)
    4. Continue with the task after summarization
    """
    call_count = {"count": 0}
    context_exceeded_triggered = {"value": False}
    hello_txt_created = {"value": False}
    hello_txt_verified = {"value": False}

    async def fake_openai_handler(request):
        """Fake OpenAI API endpoint that simulates context summarization."""
        request_data = await request.json()

        # Increment call count
        call_count["count"] += 1

        # Get the model and messages from the request
        model = request_data.get("model", "gpt-4")
        messages = request_data.get("messages", [])

        # Helper function to create response with logprobs and token IDs for rollout details
        def create_response(response_id, content, prompt_tokens, completion_tokens):
            """Create a fake OpenAI response with logprobs and token IDs for testing rollout details."""
            # Generate synthetic completion token IDs (one per completion token)
            # Use simple incremental IDs starting from 1000
            completion_token_ids = list(range(1000, 1000 + completion_tokens))

            # Generate synthetic prompt token IDs (one per prompt token)
            # Use simple incremental IDs starting from 100
            prompt_token_ids = list(range(100, 100 + prompt_tokens))

            # Generate synthetic logprobs - one per completion token
            logprobs_content = []
            for i in range(completion_tokens):
                # Create a simple token string
                token = f"tok_{i}"
                logprobs_content.append(
                    {
                        "token": token,
                        "logprob": -0.1 * (i + 1),
                        "bytes": list(token.encode("utf-8")),
                        "top_logprobs": [],
                    }
                )

            return {
                "id": response_id,
                "object": "chat.completion",
                "created": 1234567890 + call_count["count"],
                "model": model,
                "choices": [
                    {
                        "index": 0,
                        "message": {"role": "assistant", "content": content},
                        "finish_reason": "stop",
                        "logprobs": {"content": logprobs_content},
                        "token_ids": completion_token_ids,
                    }
                ],
                "usage": {
                    "prompt_tokens": prompt_tokens,
                    "completion_tokens": completion_tokens,
                    "total_tokens": prompt_tokens + completion_tokens,
                },
                "prompt_token_ids": prompt_token_ids,
            }

        print(f"[FAKE SERVER] Call #{call_count['count']} for model: {model}, messages count: {len(messages)}")

        # Check if this is a summarization request based on message content
        last_message = messages[-1] if messages else {}
        last_content = last_message.get("content", "")

        # Detect summary generation request
        if "hand off your work to another AI agent" in last_content:
            print("[FAKE SERVER] Handling summary generation request")
            response_content = """I have been working on creating hello.txt. Here's what I've accomplished:

1. **Major Actions Completed**:
   - Created a test directory with `mkdir test_dir`
   - Created file1.txt, file2.txt in the test directory
   - Attempted to list files to verify creation

2. **Important Information Learned**:
   - All test files are located in /app/test_dir/
   - The working directory is /app/
   - The terminal environment is working correctly

3. **Challenging Problems Addressed**:
   - None so far, everything has been straightforward

4. **Current Status**:
   - Test setup is partially complete
   - Still need to create the main hello.txt file with "Hello, world!" content in /app/"""

