def write_jsonl_gz():
    def _write(path: Path, records: list[dict]) -> None:
        path.parent.mkdir(parents=True, exist_ok=True)
        with gzip.open(path, "wt", encoding="utf-8") as f:
            for record in records:
                f.write(json.dumps(record))
                f.write("\n")

    return _write

def make_zip_archive(tmp_path: Path):
    def _make(name: str, files: dict[str, str]) -> Path:
        archive_path = tmp_path / name
        with zipfile.ZipFile(archive_path, "w", zipfile.ZIP_DEFLATED) as zf:
            for member_name, content in files.items():
                zf.writestr(member_name, content)
        return archive_path

    return _make

def artifact_path(tmp_path):
    """A directory holding a saved artifact, returned as an absolute uri."""
    base = tmp_path / "artifact"
    base.mkdir()
    Artifact.save(_Payload(path=str(base), value=7), str(base))
    return str(base)

def captured_uploads(monkeypatch):
    """Stub sinks.open_url so finalized files are captured in memory instead of
    hitting GCS. Returns {dest_url: decompressed_text}."""
    uploads: dict[str, bytes] = {}

    def fake_open_url(dest: str, mode: str = "rb"):
        buf = io.BytesIO()

        class _CM:
            def __enter__(self):
                return buf

            def __exit__(self, *exc):
                uploads[dest] = buf.getvalue()
                return False

        return _CM()

    monkeypatch.setattr(sinks, "open_url", fake_open_url)
    return uploads

