    x["only in x"] = results("https://x.com/")
    (tmp_path / "x.json").write_text(json.dumps(x))
    (tmp_path / "y.json").write_text(json.dumps(y))
    work = tmp_path / "work"
    batches(tmp_path / "x.json", tmp_path / "y.json", work)
    return work

def jev(monkeypatch, settings):
    settings.JEV_API_KEY = "test-key"
    monkeypatch.setattr(jev_order.time, "sleep", lambda seconds: None)
    calls = []

    def configure(*responses):
        queued = list(responses)

        def fake_post(url, json, headers, timeout):
            calls.append(json)
            return queued.pop(0)

        monkeypatch.setattr(jev_order.requests, "post", fake_post)
        return calls

    return configure

