def process_group():
    already_initialized = dist.is_available() and dist.is_initialized()
    weighted_merge_module._ensure_process_group()
    yield
    if not already_initialized and dist.is_available() and dist.is_initialized():
        if dist.get_world_size() == 1:
            dist.destroy_process_group()

def skip_single_rank_checkpoint_tests(request):
    if "tmp_path_dist_ckpt" not in request.fixturenames:
        return
    if "distributed_checkpoint_world" in request.fixturenames:
        return
    if _configured_world_size() != 1:
        pytest.skip("single-rank weighted merge fixture coverage requires world_size=1")

def distributed_checkpoint_world(process_group):
    world_size = _world_size()
    if world_size < 2:
        pytest.skip("multi-rank metadata same-layout coverage requires torchrun")
    return world_size

def cpu_only_dcp_save(monkeypatch):
    # GPTModel construction asserts on NVTE_FLASH_ATTN/NVTE_FUSED_ATTN/
    # NVTE_UNFUSED_ATTN when they are set in the env (e.g. =0 in the CI
    # container). Unset them so CPU model fixtures build (mirrors the smoke).
    for _var in ("NVTE_FLASH_ATTN", "NVTE_FUSED_ATTN", "NVTE_UNFUSED_ATTN"):
        monkeypatch.delenv(_var, raising=False)
    if torch.cuda.is_available():
        return
    # DCP's mcore async writer synchronizes CUDA even for these CPU-only fixtures.
    monkeypatch.setattr(torch.cuda, "synchronize", lambda *args, **kwargs: None)
    monkeypatch.setattr(torch.cuda, "current_device", lambda: torch.device("cpu"))
    if not filesystem_async.HAVE_PSUTIL:
        monkeypatch.setattr(filesystem_async, "_process_memory", lambda: 0)

def plugin_imports() -> Iterator[None]:
    previous_path = list(sys.path)
    previous_modules = {name: sys.modules.get(name) for name in _PLUGIN_MODULE_NAMES}
    for name in _PLUGIN_MODULE_NAMES:
        sys.modules.pop(name, None)
    sys.path.insert(0, str(PLUGIN_ROOT))
    try:
        yield
    finally:
        sys.path[:] = previous_path
        for name in _PLUGIN_MODULE_NAMES:
            sys.modules.pop(name, None)
        for name, module in previous_modules.items():
            if module is not None:
                sys.modules[name] = module

def hook_module(plugin_imports: None) -> ModuleType:
    return _load_module(
        "powercontext_workbuddy_hook",
        PLUGIN_ROOT / "hooks" / "workbuddy_powercontext_hook.py",
    )

def _isolated_plugin_environment(monkeypatch: pytest.MonkeyPatch) -> None:
    """Keep the plugin defaults under test rather than the host's environment."""

    for name in tuple(os.environ):
        if name.startswith("POWERCONTEXT_"):
            monkeypatch.delenv(name, raising=False)

def isolated_host_environment(monkeypatch, tmp_path: Path) -> Path:
    for name in tuple(os.environ):
        if name.startswith(("BUB_", "POWERCONTEXT_")) or name in {"CODEX_HOME", "GITHUB_SHA"}:
            monkeypatch.delenv(name)
    codex_home = tmp_path / "codex-home"
    codex_home.mkdir()
    monkeypatch.setenv("CODEX_HOME", str(codex_home))
    return codex_home

