def response_parser() -> Callable[[str | bytes], str | None]:
    def parse_response(message: str | bytes) -> str | None:
        if isinstance(message, bytes):
            message = message.decode()
        return json.loads(message).get("message")

    return parse_response

def message_builder() -> Callable[[str], str | bytes]:
    def build_message(prompt: str) -> str:
        return json.dumps({"message": prompt})

    return build_message

def websocket_target(
    response_parser: Callable[[str | bytes], str | None],
    message_builder: Callable[[str], str | bytes],
    sqlite_instance: SQLiteMemory,
) -> WebsocketTarget:
    return WebsocketTarget(
        endpoint="wss://example.com",
        protocol_identifier="test-protocol",
        initialization_strings=["connect", "authenticate"],
        response_parser=response_parser,
        message_builder=message_builder,
        discard_initial_messages=0,
    )

def garak_api_key_service_patterns() -> dict[str, str | None]:
    dataset = SeedDataset.from_yaml_file(
        DATASETS_PATH / "seed_datasets" / "local" / "garak" / "api_key_service_patterns.prompt"
    )
    patterns: dict[str, str | None] = {}
    for prompt in dataset.prompts:
        pattern_name = prompt.metadata["pattern_name"]
        assert pattern_name is None or isinstance(pattern_name, str)
        assert prompt.value not in patterns, f"Duplicate service: {prompt.value}"
        patterns[prompt.value] = pattern_name
    return patterns

def corpus_seeds() -> dict[str, list[Seed]]:
    directory = Path(__file__).parents[4] / "pyrit" / "datasets" / "seed_datasets" / "local" / "garak"
