            urllib.request.urlretrieve(CACHEXIA_URL, CACHEXIA_CACHE)
        except Exception as exc:  # pragma: no cover
            pytest.skip(f"Cannot fetch cachexia CSV ({exc}) — offline CI?")
    return CACHEXIA_CACHE

