def client_call():
    pytest.importorskip("mcp", reason="requires the optional [mcp] extra")
    import anyio
    from mcp import Client

    from modules.mcp_server import build_server

    server = build_server()

    def call(fn):
        async def go():
            async with Client(server) as client:
                return await fn(client)

        return anyio.run(go)

    return call

