def patch_httpx(monkeypatch):
    """Replace httpx.get with one that routes through the test transport.

    We install a fresh stub per test via the ``capture`` dict the test
    needs; tests that want the default 200 OpenAI shape can use the
    ``openai_ok`` fixture, others build their own transport.
    """
    state: dict = {"transport": None}

    def fake_get(url, **kwargs):
        if state["transport"] is None:
            raise AssertionError("Test did not register a transport via set_transport")
        with httpx.Client(transport=state["transport"]) as client:
            return client.get(url, **{k: v for k, v in kwargs.items() if k != "transport"})

    monkeypatch.setattr("openakita.llm.model_probe.httpx.get", fake_get)
    state["set"] = lambda t: state.__setitem__("transport", t)
    return state

def _disable_desktop_notifications(monkeypatch):
    """禁止测试过程中弹出真实的桌面通知。"""
    # fail-soft：模块未导入时静默跳过（pytest collection 阶段可能还没 import）
    try:
        from openakita.core import desktop_notify as _dn
    except Exception:
        return

    async def _noop_async(*_args, **_kwargs):
        return False

    def _noop_sync(*_args, **_kwargs):
        return False

    monkeypatch.setattr(_dn, "send_desktop_notification", _noop_sync, raising=False)
    monkeypatch.setattr(
        _dn, "send_desktop_notification_async", _noop_async, raising=False
    )
    monkeypatch.setattr(_dn, "notify_task_completed", _noop_sync, raising=False)
    monkeypatch.setattr(
        _dn, "notify_task_completed_async", _noop_async, raising=False
    )

    # 双保险：把 settings.desktop_notify_enabled 也置为 False，覆盖任何动态导入
    try:
        from openakita.config import settings as _settings

        monkeypatch.setattr(_settings, "desktop_notify_enabled", False, raising=False)
    except Exception:
        pass

