def sparse_df(fill_value):
    """DataFrame with sparse int columns and a dense grouping column."""
    dense = DataFrame(
        {
            "key": ["a", "a", "b", "b", "a", "b"],
            "val1": [1, 0, 0, 3, 0, 5],
            "val2": [0, 2, 0, 0, 4, 0],
        }
    )
    sparse = dense.copy()
    sparse["val1"] = sparse["val1"].astype(SparseDtype(np.int64, fill_value))
    sparse["val2"] = sparse["val2"].astype(SparseDtype(np.int64, fill_value))
    return dense, sparse

def int_arr2d(self):
        # [[1,  NA],
        #  [3,  4 ]]
        data = np.array([[1, 2], [3, 4]], dtype=np.int64)
        mask = np.array([[False, True], [False, False]], dtype=bool)
        return IntegerArray._simple_new(data, mask)

def float_arr2d(self):
        # [[1.0,  NA ],
        #  [3.0,  4.0]]
        data = np.array([[1.0, 2.0], [3.0, 4.0]], dtype=np.float64)
        mask = np.array([[False, True], [False, False]], dtype=bool)
        return FloatingArray._simple_new(data, mask)

