def source_manifest_data() -> dict[str, Any]:
    """Graph with sources -> staging -> marts.

    sources: raw.customers, raw.orders
    staging: stg_src_customers (depends on source.test.raw.customers)
             stg_src_orders (depends on source.test.raw.orders)
    marts:   src_customer_summary (depends on both stg_src models)
    """
    return {
        "nodes": {
            "model.test.stg_src_customers": {
                "name": "stg_src_customers",
                "resource_type": "model",
                "depends_on": {"nodes": ["source.test.raw.customers"]},
                "config": {"materialized": "view"},
            },
            "model.test.stg_src_orders": {
                "name": "stg_src_orders",
                "resource_type": "model",
                "depends_on": {"nodes": ["source.test.raw.orders"]},
                "config": {"materialized": "view"},
            },
            "model.test.src_customer_summary": {
                "name": "src_customer_summary",
                "resource_type": "model",
                "depends_on": {
                    "nodes": [
                        "model.test.stg_src_customers",
                        "model.test.stg_src_orders",
                    ]
                },
                "config": {"materialized": "table"},
            },
        },
        "sources": {
            "source.test.raw.customers": {
                "name": "customers",
                "resource_type": "source",
                "fqn": ["test", "raw", "customers"],
                "relation_name": '"main"."raw"."customers"',
                "config": {},
            },
            "source.test.raw.orders": {
                "name": "orders",
                "resource_type": "source",
                "fqn": ["test", "raw", "orders"],
                "relation_name": '"main"."raw"."orders"',
                "config": {},
            },
        },
    }

def dbt_project(tmp_path_factory):
    """Session-scoped dbt project with DuckDB and parsed manifest."""
    project_dir = tmp_path_factory.mktemp("dbt_freshness_project")

    for item in DBT_TEST_PROJECT.iterdir():
        dest = project_dir / item.name
        if item.is_dir():
            shutil.copytree(item, dest)
        else:
            shutil.copy2(item, dest)

    profiles = {
        "test": {
            "target": "dev",
            "outputs": {
                "dev": {
                    "type": "duckdb",
                    "path": str(project_dir / "warehouse.duckdb"),
                    "schema": "main",
                    "threads": 1,
                }
            },
        }
    }
    (project_dir / "profiles.yml").write_text(yaml.dump(profiles))

    runner = dbtRunner()
    result = runner.invoke(
        ["parse", "--project-dir", str(project_dir), "--profiles-dir", str(project_dir)]
    )
    assert result.success, f"dbt parse failed: {result.exception}"

    return {
        "project_dir": project_dir,
        "profiles_dir": project_dir,
        "manifest_path": project_dir / "target" / "manifest.json",
    }

