    geos = ["CA", "NY"]
    coords = {
        "chain": np.arange(n_chain),
        "draw": np.arange(n_draw),
        "date": dates,
        "geo": geos,
    }
    base_shape = (n_chain, n_draw, n_date, 2)

    pp = xr.Dataset(
        {
            "y": xr.DataArray(
                rng.normal(size=base_shape),
                dims=("chain", "draw", "date", "geo"),
                coords=coords,
            ),
            "y_original_scale": xr.DataArray(
                rng.normal(size=base_shape) * 100 + 500,
                dims=("chain", "draw", "date", "geo"),
                coords=coords,
            ),
        }
    )
    prior_predictive = xr.Dataset(
        {
            "y": xr.DataArray(
                rng.normal(size=base_shape),
                dims=("chain", "draw", "date", "geo"),
                coords=coords,
            ),
        }
    )
    prior = xr.Dataset(
        {
            "y_original_scale": xr.DataArray(
                rng.normal(size=base_shape) * 100 + 500,
                dims=("chain", "draw", "date", "geo"),
                coords=coords,
            ),
        }
    )
    const = xr.Dataset(
        {
            "target_data": xr.DataArray(
                rng.normal(500, 50, size=(n_date, 2)),
                dims=("date", "geo"),
                coords={"date": dates, "geo": geos},
            ),
            "target_scale": xr.DataArray(1000.0),
        }
    )
    return az.InferenceData(
        posterior_predictive=pp,
        prior_predictive=prior_predictive,
        prior=prior,
        constant_data=const,
    )

def posterior_idata() -> az.InferenceData:
    """InferenceData with posterior + prior groups for distribution plot tests."""
    rng = np.random.default_rng(SEED)
    n_chain, n_draw = 2, 50
    channels = ["tv", "radio", "social"]
    base_coords = {"chain": range(n_chain), "draw": range(n_draw)}
    chan_coords = {**base_coords, "channel": channels}

    posterior = xr.Dataset(
        {
            "alpha": xr.DataArray(
                rng.normal(size=(n_chain, n_draw, len(channels))),
                dims=("chain", "draw", "channel"),
                coords=chan_coords,
            ),
            "sigma": xr.DataArray(
                rng.normal(size=(n_chain, n_draw)),
                dims=("chain", "draw"),
                coords=base_coords,
            ),
        }
    )
    prior = xr.Dataset(
        {
            "alpha": xr.DataArray(
                rng.normal(size=(n_chain, n_draw, len(channels))),
                dims=("chain", "draw", "channel"),
                coords=chan_coords,
            ),
            "sigma": xr.DataArray(
                rng.normal(size=(n_chain, n_draw)),
                dims=("chain", "draw"),
                coords=base_coords,
            ),
        }
    )
    const = xr.Dataset(coords={"channel": channels})
    return az.InferenceData(posterior=posterior, prior=prior, constant_data=const)

