        def __call__(self, *_args, **_kwargs):
            return {
                "pred_boxes": torch.zeros(1, 1, 4),
                "pred_logits": torch.zeros(1, 1, 2),
                "pred_masks": torch.zeros(1, 1, 2, 2),
