    model = types.SimpleNamespace(
        model=types.SimpleNamespace(
            model=_DummyCoreModel(),
            device="cpu",
            resolution=14,
        ),
        model_config=types.SimpleNamespace(segmentation_head=False),
    )

    export_called: dict[str, bool] = {"value": False}

    def _fake_make_infer_image(*_args, **_kwargs):
