def can_symlink(tmp_path: Path) -> None:
    """Skip the test if symlinks are not supported on this OS."""
    target = tmp_path / "target"
    target.touch()
    try:
        tmp_path.joinpath("link").symlink_to(target)
    except OSError:
        pytest.skip(
            "Creating symlinks is not supported/allowed on this OS without privileges"
        )

def register(monkeypatch):
    """Register fake entry-point config providers.

    Call ``register(level, name, func)`` with ``level`` of "default" or
    "override" and an arbitrary ``name``.
    """
    groups: dict[str, dict[str, object]] = {
        _load_entrypoint_config.GROUP_DEFAULT: {},
        _load_entrypoint_config.GROUP_OVERRIDE: {},
    }

    def fake_entry_points(*, group: str):
        return [
            FakeEntryPoint(name, func) for name, func in groups.get(group, {}).items()
        ]

    # The loader resolves entry points through this shared compat module.
    monkeypatch.setattr(compat_metadata, "entry_points", fake_entry_points)

    def add(level: str, name: str, func: Callable[..., object]) -> None:
        group = (
            _load_entrypoint_config.GROUP_OVERRIDE
            if level == "override"
            else _load_entrypoint_config.GROUP_DEFAULT
        )
        groups[group][name] = func

    return add

def _clear_caches() -> Iterable[None]:
    """Keep process-wide caches from leaking between tests that fake their input."""
    from scikit_build_core._compat.importlib.metadata import cached_entry_points
    from scikit_build_core.builder._known_wheels import is_known_platform

    for cached in (cached_entry_points, is_known_platform):
        cached.cache_clear()
    yield
    for cached in (cached_entry_points, is_known_platform):
        cached.cache_clear()

