def random_codec() -> MimiCodec:
    """A full-size Mimi with small random weights and every codebook entry in use."""
    torch.manual_seed(0)
    codec = MimiCodec().eval()
    with torch.no_grad():
        for parameter in codec.parameters():
            parameter.normal_(std=0.05)
        for module in codec.modules():
            if hasattr(module, "embedding_sum"):
                module.embedding_sum.normal_()
                module.cluster_usage.fill_(1.0)
    return codec

def preprocess(monkeypatch, tmp_path):
    loads = []

    def load_voice_prompt(path, *, load_audio):
        loads.append(path)
        return VoicePrompt(
            frames=3,
            embeddings=torch.zeros(2, 4),
            tail_codes=torch.zeros(2, 8, dtype=torch.long),
        )

    caller = np.stack(
        [np.full(CALLER_SAMPLES, 0.5), np.full(CALLER_SAMPLES, -1.0)]
    ).astype(np.float32)
    monkeypatch.setattr(stages, "load_text_tokenizer", lambda _: FakeTokenizer())
    sources = []

    def load_audio(source, **_):
        sources.append(source)
        return caller

    monkeypatch.setattr(stages, "load_audio", load_audio)
    monkeypatch.setattr(stages, "resolve_voice_path", lambda _, voice: f"{voice}.pt")
    monkeypatch.setattr(stages, "load_voice_prompt", load_voice_prompt)
    scheduler = stages.create_preprocessing_executor(str(tmp_path))

    def run(inputs=None, **params):
        payload = StagePayload(
            "r",
            request=OmniRequest(
                inputs=inputs or {"audio_path": "caller.wav"}, params=params
            ),
            data={},
        )
        return PersonaPlexState.from_dict(scheduler.fn(payload).data)

    run.loads = loads
    run.sources = sources
    return run

def audio():
    if not _AUDIO.exists():
        pytest.skip(f"audio fixture unavailable: {_AUDIO}")
    return _AUDIO.read_bytes()

def real_speech_samples(audio):
    samples, sample_rate = sf.read(io.BytesIO(audio), dtype="float32")
    if samples.ndim > 1:
        samples = samples.mean(axis=1)
    if sample_rate != 16000:
        samples = _scipy_resample(samples, int(len(samples) * 16000 / sample_rate))
    return samples.astype(np.float32)

