def fake_run(monkeypatch):
    """Capture argv; create the requested --out file so the check passes."""
    calls = []

    def _run(cmd, **kwargs):
        calls.append((cmd, kwargs))
        args = _argv_to_map(cmd)
        if "--out" in args:
            p = Path(args["--out"])
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_bytes(b"RIFF____WAVE")
        return subprocess.CompletedProcess(cmd, 0, b"", b"")

    monkeypatch.setattr(music.subprocess, "run", _run)
    return calls

def _restore_server_globals():
    saved = {name: getattr(server, name, _MISSING) for name in _SERVER_GLOBALS}
    mcp_saved = os.environ.get("RAPID_MLX_MCP_CONFIG", _MISSING)
    try:
        yield
    finally:
        for name, value in saved.items():
            if value is _MISSING:
                if hasattr(server, name):
                    delattr(server, name)
            else:
                setattr(server, name, value)
        if mcp_saved is _MISSING:
            os.environ.pop("RAPID_MLX_MCP_CONFIG", None)
        else:
            os.environ["RAPID_MLX_MCP_CONFIG"] = mcp_saved

