def validate_input(value):
    """Validate numeric input."""
    try:
        return float(value)
    except ValueError:
        raise ValueError(f"Invalid numeric input: {value}")


class InputValidator:
    """Class for input validation operations."""

    @staticmethod
    def is_numeric(value):
        """Check if value is numeric."""
        try:
            float(value)
            return True
        except ValueError:
            return False

    @classmethod
    def validate_range(cls, value, min_val, max_val):
        """Validate that value is within range."""
        if not cls.is_numeric(value):
            return False
        num_val = float(value)
        return min_val <= num_val <= max_val
''')

    # Create config file
    (codebase_dir / "config.py").write_text('''"""Configuration settings."""

DEFAULT_PRECISION = 2
MAX_HISTORY_SIZE = 100
SUPPORTED_OPERATIONS = ["add", "subtract", "multiply", "divide"]

class Config:
    """Configuration class."""

    def __init__(self):
        self.precision = DEFAULT_PRECISION
        self.history_size = MAX_HISTORY_SIZE

    def update(self, **kwargs):
        """Update configuration."""
        for key, value in kwargs.items():
            if hasattr(self, key):
                setattr(self, key, value)
''')

