def tmp_sample(tmp_path):
    """Return a factory that writes bytes/str to a temp file and returns its path."""

    def _make(name: str, data) -> str:
        path = tmp_path / name
        mode = "wb" if isinstance(data, (bytes, bytearray)) else "w"
        with open(path, mode) as fh:
            fh.write(data)
        return str(path)

    return _make

