def exit_hook():
    class ExitHook:
        def __init__(self):
            self.should_exit = True

        def register_hooks(self, registry):
            registry.add_callback(BeforeNodeCallEvent, self.exit_before_analyst)

        def exit_before_analyst(self, event):
            if event.node_id == "analyst" and self.should_exit:
                raise SystemExit("Controlled exit before analyst")

    return ExitHook()

def verify_hook():
    class VerifyHook:
        def __init__(self):
            self.first_node = None

        def register_hooks(self, registry):
            registry.add_callback(BeforeNodeCallEvent, self.capture_first_node)

        def capture_first_node(self, event):
            if self.first_node is None:
                self.first_node = event.node_id

    return VerifyHook()

def bucket_name():
    bucket_name = f"test-strands-session-bucket-{boto3.client('sts').get_caller_identity()['Account']}"
    s3_client = boto3.resource("s3", region_name="us-west-2")
    try:
        s3_client.create_bucket(Bucket=bucket_name, CreateBucketConfiguration={"LocationConstraint": "us-west-2"})
    except ClientError as e:
        if "BucketAlreadyOwnedByYou" not in str(e):
            raise e
    yield bucket_name

