def graph(tmp_path_factory: pytest.TempPathFactory) -> dict[Edge, str]:
    """(caller, rel, target) -> resolution label, for CALLS and REFERENCES."""
    repo = _build(tmp_path_factory.mktemp("shadow"))
    parsers, queries = load_parsers()
    store = _StatefulIngestor()
    GraphUpdater(ingestor=store, repo_path=repo, parsers=parsers, queries=queries).run(
        force=True
    )
    kept = (cs.RelationshipType.CALLS.value, cs.RelationshipType.REFERENCES.value)
    edges: dict[Edge, str] = {}
    for edge in store.keyed_edges:
        _sl, src, rel, _tl, tgt, _site = edge
        if rel in kept:
            props = store.edge_props.get(edge, {})
            edges[(str(src), rel, str(tgt))] = str(
                props.get(cs.KEY_RESOLUTION, cs.EdgeResolution.EXACT.value)
            )
    return edges

def records() -> Iterator[Records]:
    captured: Records = []
    sink = logger.add(
        lambda message: captured.append(
            (message.record["level"].name, message.record["message"])
        ),
        level="DEBUG",
    )
    try:
        yield captured
    finally:
        logger.remove(sink)

def tokenizer_mock():
    """Fixture to provide a mocked tokenizer."""
    tokenizer = MagicMock(spec=PreTrainedTokenizerBase)

    # Simple tokenizer: each character is a token
    def encode_side_effect(text):
        if not text:
            return []
        # Count tokens as roughly one per character for simplicity
        return list(range(len(text)))

    def decode_side_effect(tokens, skip_special_tokens=False):
        if not tokens:
            return ""
        # Simple decode: return a string representation
        return "".join(chr(65 + (t % 26)) for t in tokens[:100])

    tokenizer.encode.side_effect = encode_side_effect
    tokenizer.decode.side_effect = decode_side_effect
    return tokenizer

