def known_rules() -> frozenset[str]:
    """Every rule the installed checker implements."""
    listing = _run("--list", cwd=REPO_ROOT).stdout
    found = frozenset(
        match.group(1)
        for line in listing.splitlines()
        if (match := re.match(rf"\s+({RULE})\s{{2,}}\S", line))
    )
    assert found, "xorq-check-style --list produced no rules"
    return found

def whole_repo_ratchet() -> frozenset[str]:
    """The --disable list the whole-repo gate passes, read from the workflow."""
    lists = re.findall(
        rf"^\s+({RULE}(?:,{RULE})+)$", WORKFLOW.read_text(), re.MULTILINE
    )
    assert len(lists) == 1, (
        f"expected one --disable list in {WORKFLOW.name}, got {len(lists)}"
    )
    return frozenset(lists[0].split(","))

def changed_lines_ratchet() -> frozenset[str]:
    """The disable list the shared changed-lines gate applies."""
    match = re.search(
        rf"^disable=({RULE}(?:,{RULE})+)$", DIFF_GATE.read_text(), re.MULTILINE
    )
    assert match, f"no disable= assignment in {DIFF_GATE.name}"
    return frozenset(match.group(1).split(","))

def add_entry(world: SimpleNamespace):
    """Add a second entry over its own table, on `world`'s database by default."""

    def add(path: Path | None = None, table: str = "u"):
        con = SqliteBackend().connect(str(path or world.db_path))
        con.create_table(table, RECORDED.to_pandas())
        return world.catalog.add(con.table(table))

    return add

def record(world: SimpleNamespace) -> BuildRecord:
    """The parsed build, without probing anything."""
    return BuildRecord.from_catalog_entry(world.catalog.get_catalog_entry(world.name))

def connects(monkeypatch: pytest.MonkeyPatch) -> list[str]:
    """Every `Profile.get_con` call the command makes."""
    calls = []
    get_con = Profile.get_con

    def counted(self, *args, **kwargs):
        calls.append(self.con_name)
        return get_con(self, *args, **kwargs)

    monkeypatch.setattr(Profile, "get_con", counted)
    return calls

def world(con: SqliteBackend, builds_dir: Path) -> tuple:
    """A build of `t.filter(t.a > 1)`: `a` is referenced, `b` is not."""
    t = con.table("t")
    return con, build_expr(t.filter(t.a > 1), builds_dir=builds_dir)

def schema(live_config: RedshiftLiveConfig) -> str:
    schema, _ = live_config["XORQ_REDSHIFT_PROBE_TABLE"].split(".")
    return schema

def con(live_config: RedshiftLiveConfig, schema: str) -> RedshiftBackend:
    con = connect(live_config, schema)
    if MATRIX_TABLE not in con.list_tables(database=schema):
        con.disconnect()
        pytest.skip(
            f"{schema}.{MATRIX_TABLE} does not exist; create it with "
            f"{matrix_ddl(schema)}; {matrix_insert(schema)}"
        )
    yield con
    con.disconnect()

def read_path(
    request: pytest.FixtureRequest, monkeypatch: pytest.MonkeyPatch
) -> dict[str, Any]:
    """Force the read path, and record which one actually served each read.

    A read that returns the right rows proves nothing about ADBC by itself,
    because the psycopg fallback returns the same rows.
    """
    if request.param == "adbc":
        pytest.importorskip("adbc_driver_postgresql")
    else:
        monkeypatch.setattr(
            RedshiftBackend,
            "_adbc_unavailable_reason",
            lambda self: "forced off by the test",
        )
    record = {"path": request.param, "adbc_opens": 0, "psycopg_reads": 0}
    real_open = RedshiftBackend._open_adbc_conn_or_none
    real_gen_name = ibis_util.gen_name

    def spy_open(self: RedshiftBackend) -> Any:
        conn = real_open(self)
        record["adbc_opens"] += conn is not None
        return conn

    def spy_gen_name(namespace: str) -> str:
        # Only the psycopg branch of to_pyarrow_batches names a cursor so.
        record["psycopg_reads"] += namespace == "postgres_cursor"
        return real_gen_name(namespace)

    monkeypatch.setattr(RedshiftBackend, "_open_adbc_conn_or_none", spy_open)
    monkeypatch.setattr(ibis_util, "gen_name", spy_gen_name)
    return record

