def release_module() -> ModuleType:
    """Load the script as a module after proving the expected file exists."""
    if not SCRIPT_PATH.exists():

        class MissingReleaseModule:
            def __getattr__(self, _name: str) -> object:
                raise AssertionError("scripts/release.py has not been implemented")

        return cast("ModuleType", MissingReleaseModule())
    spec = importlib.util.spec_from_file_location("release_script", SCRIPT_PATH)
    assert spec is not None and spec.loader is not None
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module

def split_jobs(tmp_path: Path) -> Settings:
    jobs = tmp_path / "jobs"
    ocr_root = jobs / OCR_JOB
    translate_root = jobs / TRANSLATE_JOB

    _write(
        ocr_root / "ocr" / "normalized" / "document.v1.json",
        {
            "schema": "document.v1",
            "document_id": DOCUMENT_ID,
            "page_count": 1,
            "pages": [
                {
                    "page_index": 0,
                    "blocks": [
                        {
                            "block_id": "p001-b0000",
                            "page_index": 0,
                            "order": 0,
                            "type": "text",
                            "text": "Conical intersections govern nonadiabatic dynamics.",
                        }
                    ],
                }
            ],
        },
    )
    _write(ocr_root / "md" / "full.md", "# Title\n\nConical intersections.\n")
    # 翻译 job 只有译文，以及一份指回 OCR job 的溯源记录。
    _write(
        translate_root / "translated" / "page-001-deepseek.json",
        [
            {
                "item_id": "p001-b000",
                "page_idx": 0,
                "block_idx": 0,
                "translated_text": "锥形交叉支配非绝热动力学。",
            }
        ],
    )
    _write(
        translate_root / "artifacts" / "pipeline_summary.json",
        {"source_pdf": str(ocr_root / "source" / "book.pdf")},
    )
    return Settings(data_root=tmp_path)

