def _restore_anthropic_env():
    saved = {k: os.environ.get(k) for k in _ANTHROPIC_ENV_KEYS}
    yield
    for k, v in saved.items():
        if v is None:
            os.environ.pop(k, None)
        else:
            os.environ[k] = v

