def _flush_auth_redis(flask_app: Flask) -> Generator[None, None, None]:
    def _flush():
        with flask_app.app_context():
            for k in redis_client.keys("auth:*"):
                redis_client.delete(k)
            for k in redis_client.keys("rl:*"):
                redis_client.delete(k)

    _flush()
    yield
    _flush()

